brief:
Your team is migrating a legacy Node.js service from callbacks to async/await. Here is a function you need to modernise:

```javascript
// reportService.js
const db = require('./db');
const fs = require('fs');
const https = require('https');

function generateUserReport(userId, outputPath, webhookUrl, callback) {
  db.query('SELECT * FROM users WHERE id = $1', [userId], function(err, rows) {
    if (err) return callback(err);
    if (!rows.length) return callback(new Error('User not found'));
    const user = rows[0];

    const reportContent = JSON.stringify({ user, generatedAt: new Date() });

    fs.writeFile(outputPath, reportContent, function(err) {
      if (err) return callback(err);

      const reqBody = JSON.stringify({ userId, reportPath: outputPath });
      const options = {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(reqBody) }
      };
      const req = https.request(webhookUrl, options, function(res) {
        let data = '';
        res.on('data', chunk => { data += chunk; });
        res.on('end', function() {
          if (res.statusCode >= 400) {
            return callback(new Error(`Webhook failed: ${res.statusCode}`));
          }
          callback(null, { userId, reportPath: outputPath, webhookStatus: res.statusCode });
        });
      });
      req.on('error', callback);
      req.write(reqBody);
      req.end();
    });
  });
}

module.exports = { generateUserReport };
```

**Your tasks:**
1. Rewrite `generateUserReport` as an `async` function that returns a Promise and uses `await` throughout — remove the `callback` parameter entirely.
2. Replace the raw `https.request` callback with a helper function `postWebhook(url, body)` that returns a Promise.
3. Use `fs.promises.writeFile` instead of the callback-based `fs.writeFile`.
4. Propagate errors naturally via `throw` / rejected Promises (callers use try/catch or `.catch()`).
5. Both visible tests must pass against the refactored code.

