const db = require('./db');
const fs = require('fs');
const https = require('https');

/**
 * POST a JSON body to a URL and resolve with the status code.
 * Rejects if the network request fails or the server returns >= 400.
 *
 * @param {string} url
 * @param {object} body
 * @returns {Promise<number>} HTTP status code
 */
function postWebhook(url, body) {
  return new Promise((resolve, reject) => {
    const reqBody = JSON.stringify(body);
    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(reqBody),
      },
    };
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode >= 400) {
          reject(new Error(`Webhook failed: ${res.statusCode}`));
        } else {
          resolve(res.statusCode);
        }
      });
    });
    req.on('error', reject);
    req.write(reqBody);
    req.end();
  });
}

/**
 * Generate a JSON report for a user, write it to disk, and notify a webhook.
 *
 * @param {string} userId
 * @param {string} outputPath
 * @param {string} webhookUrl
 * @returns {Promise<{ userId: string, reportPath: string, webhookStatus: number }>}
 */
async function generateUserReport(userId, outputPath, webhookUrl) {
  const rows = await db.query('SELECT * FROM users WHERE id = $1', [userId]);
  if (!rows.length) throw new Error('User not found');
  const user = rows[0];

  const reportContent = JSON.stringify({ user, generatedAt: new Date() });
  await fs.promises.writeFile(outputPath, reportContent);

  const webhookStatus = await postWebhook(webhookUrl, { userId, reportPath: outputPath });
  return { userId, reportPath: outputPath, webhookStatus };
}

module.exports = { generateUserReport, postWebhook };
